"""matplotlib._tight_bbox — adjust the figure's bbox before savefig.

Upstream temporarily resizes the figure to ``bbox_inches`` so that the
saved file crops to just the artist area, then restores the original
size. The plotly backend handles cropping itself when exporting, so
we just remember the inputs so callers that introspect them get back
sensible values.
"""


def adjust_bbox(fig, bbox_inches, fixed_dpi=None):
    """Resize ``fig`` so the saved output is exactly ``bbox_inches``
    inches in each direction. Returns a callable that restores the
    figure to its pre-adjustment state (mirrors upstream's contract).
    """
    if fig is None:
        return lambda: None
    # Remember the pre-adjustment size + dpi so the restore callback
    # can put them back after savefig finishes.
    orig_size = fig.get_size_inches() if hasattr(fig, 'get_size_inches') else (8, 6)
    orig_dpi = fig.get_dpi() if hasattr(fig, 'get_dpi') else 100
    try:
        if hasattr(bbox_inches, 'width') and hasattr(bbox_inches, 'height'):
            new_w, new_h = bbox_inches.width, bbox_inches.height
        elif hasattr(bbox_inches, '__iter__'):
            seq = list(bbox_inches)
            if len(seq) == 4:
                # (x0, y0, x1, y1) → (width, height)
                new_w, new_h = seq[2] - seq[0], seq[3] - seq[1]
            elif len(seq) == 2:
                new_w, new_h = seq
            else:
                new_w, new_h = orig_size
        else:
            new_w, new_h = orig_size
        fig.set_size_inches(new_w, new_h, forward=False)
        if fixed_dpi is not None and hasattr(fig, 'set_dpi'):
            fig.set_dpi(fixed_dpi)
    except Exception:
        pass

    def _restore():
        try:
            fig.set_size_inches(orig_size[0], orig_size[1], forward=False)
            if hasattr(fig, 'set_dpi'):
                fig.set_dpi(orig_dpi)
        except Exception:
            pass
    return _restore


def process_figure_for_rasterizing(fig, bbox_inches_restore, fixed_dpi=None):
    """Apply the bbox adjustment + dpi pin used during rasterized
    savefig. Returns the restore callback (same contract as
    :func:`adjust_bbox`)."""
    bbox_inches, restore_bbox = bbox_inches_restore \
        if isinstance(bbox_inches_restore, tuple) else (bbox_inches_restore, None)
    new_restore = adjust_bbox(fig, bbox_inches, fixed_dpi)

    def _combined():
        new_restore()
        if callable(restore_bbox):
            restore_bbox()
    return _combined
